B.aTF=new A.a("\u0639\u0646 \u0639\u0627\u0626\u0634\u0629 \u0623\u0645 \u0627\u0644\u0645\u0624\u0645\u0646\u064a\u0646 \u0642\u0627\u0644\u062a: \u0643\u0627\u0646 \u0644\u0627 \u064a\u062e\u0637\u0626 \u0631\u0633\u0648\u0644 \u0627\u0644\u0644\u0647 \ufdfa \u0623\u0646 \u064a\u0623\u062a\u064a \u0628\u064a\u062a \u0623\u0628\u064a \u0628\u0643\u0631 \u0623\u062d\u062f \u0637\u0631\u0641\u064a \u0627\u0644\u0646\u0647\u0627\u0631\u060c \u0625\u0645\u0627 \u0628\u0643\u0631\u0629\u060c \u0648\u0625\u0645\u0627 \u0639\u0634\u064a\u0629\u060c \u062d\u062a\u0649 \u0625\u0630\u0627 \u0643\u0627\u0646 \u0627\u0644\u064a\u0648\u0645 \u0627\u0644\u0630\u064a \u0623\u0630\u0646 \u0641\u064a\u0647 \u0644\u0631\u0633\u0648\u0644 \u0627\u0644\u0644\u0647 \ufdfa \u0641\u064a \u0627\u0644\u0647\u062c\u0631\u0629\u060c \u0648\u0627\u0644\u062e\u0631\u0648\u062c \u0645\u0646 \u0645\u0643\u0629 \u0645\u0646 \u0628\u064a\u0646 \u0638\u0647\u0631\u064a \u0642\u0648\u0645\u0647\u060c \u0623\u062a\u0627\u0646\u0627 \u0631\u0633\u0648\u0644 \u0627\u0644\u0644\u0647 \ufdfa \u0628\u0627\u0644\u0647\u0627\u062c\u0631\u0629 -\u0628\u064a\u0646 \u0627\u0644\u0636\u062d\u0649 \u0648\u0627\u0644\u0638\u0647\u064a\u0631\u0629- \u060c \u0641\u064a \u0633\u0627\u0639\u0629 \u0643\u0627\u0646 \u0644\u0627 \u064a\u0623\u062a\u064a \u0641\u064a\u0647\u0627\u060c \u0642\u0627\u0644\u062a: \u0641\u0644\u0645\u0627 \u0631\u0622\u0647 \u0623\u0628\u0648 \u0628\u0643\u0631\u060c \u0642\u0627\u0644: \u0645\u0627 \u062c\u0627\u0621 \u0631\u0633\u0648\u0644 \u0627\u0644\u0644\u0647 \ufdfa \u0647\u0630\u0647 \u0627\u0644\u0633\u0627\u0639\u0629 \u0625\u0644\u0627 \u0644\u0623\u0645\u0631 \u062d\u062f\u062b.",null)
B.aNa=new A.a("\u0642\u0627\u0644\u062a: \u0641\u0644\u0645\u0627 \u062f\u062e\u0644\u060c \u062a\u0623\u062e\u0631 \u0644\u0647 \u0623\u0628\u0648 \u0628\u0643\u0631 \u0639\u0646 \u0633\u0631\u064a\u0631\u0647\u060c \u0641\u062c\u0644\u0633 \u0631\u0633\u0648\u0644 \u0627\u0644\u0644\u0647 \ufdfa \u0648\u0644\u064a\u0633 \u0639\u0646\u062f \u0623\u0628\u064a \u0628\u0643\u0631 \u0625\u0644\u0627 \u0623\u0646\u0627 \u0648\u0623\u062e\u062a\u064a \u0623\u0633\u0645\u0627\u0621 \u0628\u0646\u062a \u0623\u0628\u064a \u0628\u0643\u0631\u060c \u0641\u0642\u0627\u0644 \u0631\u0633\u0648\u0644 \u0627\u0644\u0644\u0647 \ufdfa: \u0623\u062e\u0631\u062c \u0639\u0646\u064a \u0645\u0646 \u0639\u0646\u062f\u0643 \u0641\u0642\u0627\u0644: \u064a\u0627 \u0631\u0633\u0648\u0644 \u0627\u0644\u0644\u0647 \u0625\u0646\u0645\u0627 \u0647\u0645\u0627 \u0627\u0628\u0646\u062a\u0627\u064a\u060c \u0648\u0645\u0627 \u0630\u0627\u0643\u060c \u0641\u062f\u0627\u0643 \u0623\u0628\u064a \u0648\u0623\u0645\u064a! \u0641\u0642\u0627\u0644: \u0625\u0646\u0647 \u0642\u062f \u0623\u0630\u0646 \u0644\u064a \u0641\u064a \u0627\u0644\u062e\u0631\u0648\u062c \u0648\u0627\u0644\u0647\u062c\u0631\u0629 \u0642\u0627\u0644\u062a: \u0641\u0642\u0627\u0644 \u0623\u0628\u0648 \u0628\u0643\u0631: \u0627\u0644\u0635\u062d\u0628\u0629 \u064a\u0627 \u0631\u0633\u0648\u0644 \u0627\u0644\u0644\u0647\u061f \u0642\u0627\u0644: \u0627\u0644\u0635\u062d\u0628\u0629 \u0642\u0627\u0644\u062a: \u0641\u0648\u0627\u0644\u0644\u0647 \u0645\u0627 \u0634\u0639\u0631\u062a \u0642\u0637 \u0642\u0628\u0644 \u0630\u0644\u0643 \u0627\u0644\u064a\u0648\u0645 \u0623\u062d\u062f\u064b\u0627 \u064a\u0628\u0643\u064a \u0645\u0646 \u0627\u0644\u0641\u0631\u062d\u060c \u062d\u062a\u0649 \u0631\u0623\u064a\u062a \u0623\u0628\u0627 \u0628\u0643\u0631 \u064a\u0628\u0643\u064a \u064a\u0648\u0645\u0626\u0630\u060c \u062b\u0645 \u0642\u0627\u0644: \u064a\u0627 \u0646\u0628\u064a \u0627\u0644\u0644\u0647\u060c \u0625\u0646 \u0647\u0627\u062a\u064a\u0646 \u0631\u0627\u062d\u0644\u062a\u0627\u0646 \u0642\u062f \u0643\u0646\u062a \u0623\u0639\u062f\u062f\u062a\u0647\u0645\u0627 \u0644\u0647\u0630\u0627\u060c \u0641\u0627\u0633\u062a\u0623\u062c\u0631\u0627 \u0639\u0628\u062f \u0627\u0644\u0644\u0647 \u0628\u0646 \u0623\u0631\u064a\u0642\u0637 \u0631\u062c\u0644\u0627\u064b \u0645\u0646 \u0628\u0646\u064a \u0627\u0644\u062f\u064a\u0644 \u0628\u0646 \u0628\u0643\u0631\u060c \u0648\u0643\u0627\u0646\u062a \u0623\u0645\u0647 \u0627\u0645\u0631\u0623\u0629 \u0645\u0646 \u0628\u0646\u064a \u0633\u0647\u0645 \u0628\u0646 \u0639\u0645\u0631\u0648\u060c \u0648\u0643\u0627\u0646 \u0645\u0634\u0631\u0643\u064b\u0627 \u064a\u062f\u0644\u0647\u0645\u0627 \u0639\u0644\u0649 \u0627\u0644\u0637\u0631\u064a\u0642\u060c \u0641\u062f\u0641\u0639\u0627 \u0625\u0644\u064a\u0647 \u0631\u0627\u062d\u0644\u062a\u064a\u0647\u0645\u0627 \u0641\u0643\u0627\u0646\u062a\u0627 \u0639\u0646\u062f\u0647 \u064a\u0631\u0639\u0627\u0647\u0627 \u0644\u0645\u064a\u0639\u0627\u062f\u0647\u0645\u0627.",null)
