B.aMW=new A.a("\u0627\u0644\u0641\u0635\u0627\u062d\u0629 \u0648\u0627\u0644\u0648\u0636\u0648\u062d: \u0648\u0642\u062f \u0637\u0644\u0628 \u0645\u0648\u0633\u0649 \u062a\u062f\u0639\u064a\u0645\u0647 \u0628\u0645\u0648\u0642\u0641 \u0627\u0644\u0641\u0635\u0627\u062d\u0629 \u0645\u0646 \u0647\u0627\u0631\u0648\u0646 \u0623\u062e\u064a\u0647: \u0648\u064e\u0627\u062c\u0652\u0639\u064e\u0644\u0652 \u0644\u0650\u064a \u0648\u064e\u0632\u0650\u064a\u0631\u064b\u0627 \u0645\u0650\u0646\u0652 \u0623\u064e\u0647\u0652\u0644\u0650\u064a \u0647\u064e\u0627\u0631\u064f\u0648\u0646\u064e \u0623\u064e\u062e\u0650\u064a \u0627\u0634\u0652\u062f\u064f\u062f\u0652 \u0628\u0650\u0647\u0650 \u0623\u064e\u0632\u0652\u0631\u0650\u064a - \u0633\u0648\u0631\u0629 \u0637\u0647\u060c \u0648\u0642\u062f \u0627\u062e\u062a\u0627\u0631 \u0627\u0644\u0631\u0633\u0648\u0644 \ufdfa \u0643\u0644 \u0633\u0641\u0631\u0627\u0626\u0647 \u0648\u0645\u0628\u0639\u0648\u062b\u064a\u0647 \u0645\u0646 \u0627\u0644\u0639\u0631\u0628 \u0627\u0644\u0630\u064a\u0646 \u062a\u0631\u0628\u0648\u0627 \u0641\u064a \u0627\u0644\u062c\u0632\u064a\u0631\u0629 \u0627\u0644\u0639\u0631\u0628\u064a\u0629 \u0648\u0645\u0639 \u0627\u0644\u0628\u062f\u0648 \u0623\u062d\u064a\u0627\u0646\u0627\u064b \u0641\u0642\u062f \u0643\u0627\u0646\u0648\u0627 \u0623\u0635\u062d\u0627\u0628 \u0646\u0642\u0627\u0648\u0629 \u0648\u0644\u0645 \u062a\u062a\u0643\u062f\u0631 \u0628\u0627\u062e\u062a\u0644\u0627\u0637 \u0627\u0644\u0623\u0639\u0627\u062c\u0645 \u0628\u0639\u062f\u060c \u0641\u0642\u062f \u0643\u0627\u0646\u0648\u0627 \u0639\u0644\u0649 \u0642\u062f\u0631 \u0643\u0628\u064a\u0631 \u0645\u0646 \u0627\u0644\u0641\u0635\u0627\u062d\u0629 \u0648\u0627\u0644\u0648\u0636\u0648\u062d.",null)
