B.bbT=new A.a("\u062b\u0645 \u0623\u0645\u0631 \u0631\u0633\u0648\u0644 \ufdfa \u0641\u0633\u064f\u062d\u0650\u0628\u0648\u0627 \u0625\u0644\u0649 \u0642\u0644\u064a\u0628 \u0645\u0646 \u0642\u0644\u0628 \u0628\u062f\u0631 \u0641\u0637\u0631\u062d\u0648\u0627 \u0641\u064a\u0647 \u062b\u0645 \u0648\u0642\u0641 \u0639\u0644\u064a\u0647\u0645 \u0641\u0642\u0627\u0644: \u064a\u0627\u0639\u062a\u0628\u0629 \u0628\u0646 \u0631\u0628\u064a\u0639\u0629 \u0648\u064a\u0627\u0634\u064a\u0628\u0629 \u0628\u0646 \u0631\u0628\u064a\u0639\u0629 \u0648\u064a\u0627\u0641\u0644\u0627\u0646 \u0648\u064a\u0627\u0641\u0644\u0627\u0646 \u0647\u0644 \u0648\u062c\u062f\u062a\u0645 \u0645\u0627\u0648\u0639\u062f\u0643\u0645 \u0631\u0628\u0643\u0645 \u062d\u0642\u0627 \u0641\u0625\u0646\u064a \u0648\u062c\u062f\u062a \u0645\u0627\u0648\u0639\u062f\u0646\u064a \u0631\u0628\u064a \u062d\u0642\u0627 \u0641\u0642\u0627\u0644 \u0639\u0645\u0631 \u0628\u0646 \u0627\u0644\u062e\u0637\u0627\u0628: \u064a\u0627\u0631\u0633\u0648\u0644 \u0627\u0644\u0644\u0647! \u0645\u0627\u062a\u062e\u0627\u0637\u0628 \u0645\u0646 \u0623\u0642\u0648\u0627\u0645 \u0642\u062f \u062c\u064a\u0651\u064e\u0641\u0648\u0627\u061f \u0641\u0642\u0627\u0644: \u0648\u0627\u0644\u0630\u064a \u0646\u0641\u0633\u064a \u0628\u064a\u062f\u0647 \u0645\u0627 \u0623\u0646\u062a\u0645 \u0628\u0623\u0633\u0645\u0639 \u0644\u0645\u0627 \u0623\u0642\u0648\u0644 \u0645\u0646\u0647\u0645 \u0648\u0644\u0643\u0646\u0647\u0645 \u0644\u0627 \u064a\u0633\u062a\u0637\u064a\u0639\u0648\u0646 \u0627\u0644\u062c\u0648\u0627\u0628 \u0642\u0627\u0644 \u0642\u062a\u0627\u062f\u0629: \u0623\u062d\u064a\u0627\u0647\u0645 \u0627\u0644\u0644\u0647 \u062d\u062a\u0649 \u0623\u0633\u0645\u0639\u0647\u0645 \u0642\u0648\u0644\u0647 \u062a\u0648\u0628\u064a\u062e\u0627\u064b \u0648\u062a\u0635\u063a\u064a\u0631\u0627\u064b \u0648\u0646\u0642\u0645\u0629 \u0648\u062d\u0633\u0631\u0629 \u0648\u0646\u062f\u0645\u0627\u064b.",null)
B.b06=new A.a("\u0625\u0646 \u0647\u0630\u0629 \u0627\u0644\u0645\u0646\u0627\u062f\u0627\u0629 \u0644\u0642\u062a\u0644\u0649 \u0642\u0631\u064a\u0634 \u0628\u064a\u0646\u062a \u0623\u0645\u0631\u0627\u064b \u0639\u0638\u064a\u0645\u0627\u064b \u0648\u0647\u0648 \u0623\u0646\u0647\u0645 \u0628\u062f\u0623\u0648\u0627 \u062d\u064a\u0627\u0629 \u062c\u062f\u064a\u062f\u0629 \u0647\u064a \u062d\u064a\u0627\u0629 \u0627\u0644\u0628\u0631\u0632\u062e \u0627\u0644\u062e\u0627\u0635\u0629 \u0648\u0647\u0645 \u0641\u064a\u0647\u0627 \u064a\u0633\u0645\u0639\u0648\u0646 \u0643\u0644\u0627\u0645 \u0627\u0644\u0623\u062d\u064a\u0627\u0621 \u063a\u064a\u0631 \u0623\u0646\u0647\u0645 \u0644\u0627 \u064a\u062c\u064a\u0628\u0648\u0646 \u0648\u0644\u0627 \u064a\u062a\u0643\u0644\u0645\u0648\u0646 \u0648\u0627\u0644\u0625\u064a\u0645\u0627\u0646 \u0628\u0647\u0630\u0647 \u0627\u0644\u062d\u064a\u0627\u0629 \u0645\u0646 \u0639\u0642\u0627\u0626\u062f \u0627\u0644\u0645\u0633\u0644\u0645\u064a\u0646 \u0648\u0646\u0639\u064a\u0645 \u0627\u0644\u0642\u0628\u0631 \u0648\u0639\u0630\u0627\u0628\u0647 \u062b\u0627\u0628\u062a\u0627\u0646 \u0641\u064a \u0635\u062d\u0627\u062d \u0627\u0644\u0623\u062d\u0627\u062f\u064a\u062b \u062d\u062a\u0649 \u0625\u0646\u0647 \ufdfa \u0645\u0631\u0651 \u0628\u0642\u0628\u0631 \u0641\u0642\u0627\u0644 \u0625\u0646\u0647\u0645\u0627 \u064a\u0639\u0630\u0628\u0627\u0646 \u0648\u0645\u0627\u064a\u0639\u0630\u0628\u0627\u0646 \u0641\u064a \u0643\u0628\u064a\u0631 \u0648\u0630\u0643\u0631 \u0623\u0646 \u0633\u0628\u0628 \u062a\u0639\u0630\u064a\u0628\u0647\u0645\u0627 \u0627\u0644\u0646\u0645\u0651\u064f \u0628\u064a\u0646 \u0627\u0644\u0646\u0627\u0633 \u0648\u0639\u062f\u0645 \u0627\u0644\u0627\u0633\u062a\u0646\u0632\u0627\u0647 \u0645\u0646 \u0627\u0644\u0628\u0648\u0644.",null)
B.b2L=new A.a("\u0648\u0644\u0627\u0628\u062f \u0645\u0646 \u0627\u0644\u062a\u0633\u0644\u064a\u0645 \u0628\u0647\u0630\u0647 \u0627\u0644\u062d\u0642\u0627\u0626\u0642 \u0627\u0644\u063a\u064a\u0628\u064a\u0629 \u0628\u0639\u062f \u0623\u0646 \u062a\u062d\u062f\u062b \u0639\u0646\u0647\u0627 \u0627\u0644\u0635\u0627\u062f\u0642 \u0627\u0644\u0645\u0635\u062f\u0648\u0642 \u0648\u0642\u0637\u0639 \u0628\u0647\u0627 \u0627\u0644\u0642\u0631\u0622\u0646 \u0627\u0644\u0643\u0631\u064a\u0645 \u0641\u064a \u062a\u0639\u0630\u064a\u0628 \u0622\u0644 \u0641\u0631\u0639\u0648\u0646 \u0642\u0627\u0644 \u062a\u0639\u0627\u0644\u0649: \u0627\u0644\u0646\u0651\u064e\u0627\u0631\u064f \u064a\u064f\u0639\u0652\u0631\u064e\u0636\u064f\u0648\u0646\u064e \u0639\u064e\u0644\u064e\u064a\u0652\u0647\u064e\u0627 \u063a\u064f\u062f\u064f\u0648\u0651\u064b\u0627 \u0648\u064e\u0639\u064e\u0634\u0650\u064a\u0651\u064b\u0627 \u0648\u064e\u064a\u064e\u0648\u0652\u0645\u064e \u062a\u064e\u0642\u064f\u0648\u0645\u064f \u0627\u0644\u0633\u0651\u064e\u0627\u0639\u064e\u0629\u064f \u0623\u064e\u062f\u0652\u062e\u0650\u0644\u064f\u0648\u0627 \u0621\u064e\u0627\u0644\u064e \u0641\u0650\u0631\u0652\u0639\u064e\u0648\u0652\u0646\u064e \u0623\u064e\u0634\u064e\u062f\u0651\u064e \u0627\u0644\u0652\u0639\u064e\u0630\u064e\u0627\u0628\u0650 - \u0633\u0648\u0631\u0629 \u063a\u0627\u0641\u0631",null)
B.bc2=new A.a("\u0648\u0623\u0645\u0627 \u0627\u0644\u0634\u0647\u062f\u0627\u0621 \u0641\u0642\u062f \u0642\u0627\u0644 \u0627\u0644\u0644\u0647 \u062a\u0639\u0627\u0644\u0649 \u0641\u064a\u0647\u0645: \u0648\u064e\u0644\u0627 \u062a\u064e\u062d\u0652\u0633\u064e\u0628\u064e\u0646\u0651\u064e \u0627\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0642\u064f\u062a\u0650\u0644\u064f\u0648\u0627 \u0641\u0650\u064a \u0633\u064e\u0628\u0650\u064a\u0644\u0650 \u0627\u0644\u0644\u0651\u064e\u0647\u0650 \u0623\u064e\u0645\u0652\u0648\u064e\u0627\u062a\u064b\u0627 \u0628\u064e\u0644\u0652 \u0623\u064e\u062d\u0652\u064a\u064e\u0627\u0621\u064c \u0639\u0650\u0646\u0652\u062f\u064e \u0631\u064e\u0628\u0651\u0650\u0647\u0650\u0645\u0652 \u064a\u064f\u0631\u0652\u0632\u064e\u0642\u064f\u0648\u0646\u064e - \u0633\u0648\u0631\u0629 \u0622\u0644 \u0639\u0645\u0631\u0627\u0646",null)
